	ULyraRecoilProfile* InProfile,
	FString& OutError,
	TArray<FName>& OutInlinedCurveNames)
{
	// 旧快照必须彻底释放，避免"新旧参数混合"（计划 §10.3）。
	SnapshotStrongRef.Reset();
