void SLyraRecoilPreview::SetPoseState(EPoseState InState)
{
	FLyraRecoilPreviewConfig NewConfig = Controller->GetConfig();

	if (NewConfig.InputScript.Num() == 0)
	{
		FLyraRecoilPreviewInputEntry Entry;
		Entry.TimeSeconds = 0.0f;
		Entry.AimPitchDegrees = NewConfig.BurstStartAnglePitch;
		Entry.AimYawDegrees = NewConfig.BurstStartAngleYaw;
		Entry.PoseState = InState;
		NewConfig.InputScript.Add(Entry);
	}
	else
	{
		// 全程使用同一姿态：把脚本里所有条目的姿态改为新值，避免半途切换造成歧义。
		for (FLyraRecoilPreviewInputEntry& Entry : NewConfig.InputScript)
		{
			Entry.PoseState = InState;
		}
	}

	Controller->SetConfig(NewConfig);
	Controller->Run();
}

void SLyraRecoilPreview::SetAimingAlpha(float InValue)
{
	FLyraRecoilPreviewConfig NewConfig = Controller->GetConfig();

	if (NewConfig.InputScript.Num() == 0)
	{
		FLyraRecoilPreviewInputEntry Entry;
		Entry.TimeSeconds = 0.0f;
		Entry.AimPitchDegrees = NewConfig.BurstStartAnglePitch;
		Entry.AimYawDegrees = NewConfig.BurstStartAngleYaw;
		Entry.AimingAlpha = FMath::Clamp(InValue, 0.0f, 1.0f);
		NewConfig.InputScript.Add(Entry);
	}
	else
	{
		for (FLyraRecoilPreviewInputEntry& Entry : NewConfig.InputScript)
		{
			Entry.AimingAlpha = FMath::Clamp(InValue, 0.0f, 1.0f);
		}
	}

	Controller->SetConfig(NewConfig);
	Controller->Run();
}

void SLyraRecoilPreview::SetSingleShotModeOverride(ELyraRecoilPreviewSingleShotMode InMode)
{
	FLyraRecoilPreviewConfig NewConfig = Controller->GetConfig();
	NewConfig.SingleShotModeOverride = InMode;
	Controller->SetConfig(NewConfig);
	Controller->Run();
}

void SLyraRecoilPreview::ApplyFireScript(bool bTwoBursts)
{
	FLyraRecoilPreviewConfig NewConfig = Controller->GetConfig();
	const int32 HalfShots = FMath::Max(1, NewConfig.ShotCount / 2);
	const float RPM = FMath::Max(NewConfig.RPM, 1.0f);
	const float BurstSeconds = (60.0f / RPM) * static_cast<float>(HalfShots - 1);

	NewConfig.FireInputs.Reset();

	FLyraRecoilPreviewFireInput FirstBurst;
	FirstBurst.StartTimeSeconds = 0.0f;
	FirstBurst.ShotCount = bTwoBursts ? HalfShots : NewConfig.ShotCount;
	FirstBurst.RPM = RPM;
	NewConfig.FireInputs.Add(FirstBurst);

	if (bTwoBursts)
	{
		FLyraRecoilPreviewFireInput SecondBurst;
		// 第二轮在回正途中重开火：留出半个连发时长 + 一段回正时间。
		SecondBurst.StartTimeSeconds = BurstSeconds + 0.35f;
		SecondBurst.ShotCount = NewConfig.ShotCount - HalfShots;
		SecondBurst.RPM = RPM;
		NewConfig.FireInputs.Add(SecondBurst);
	}

	Controller->SetConfig(NewConfig);
	Controller->Run();
}

